//go:build integration

package rabbitmqclient

import (
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"testing"

	streamamqp "github.com/rabbitmq/rabbitmq-stream-go-client/pkg/amqp"
	"github.com/rabbitmq/rabbitmq-stream-go-client/pkg/stream"
)

// Certificates generated by the rabbitmq-certs compose service (docker/rabbitmq/tls/generate-certs.sh).
func tlsFile(t *testing.T, name string) string {
	t.Helper()
	dir := os.Getenv("RABBITMQ_TLS_DIR")
	if dir == "" {
		dir = filepath.Join("..", "..", "docker", "rabbitmq", "tls", "generated")
	}
	content, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		t.Fatalf("reading %s (start the broker with `docker compose up -d --wait rabbitmq`): %v", name, err)
	}
	return string(content)
}

func tlsTestOptions(t *testing.T) *RabbitMQStreamOptions {
	opts := NewRabbitMQStreamOptions()
	opts.Host = brokerHost()
	opts.IsTLS = true
	opts.AmqpPort, opts.StreamPort = 5671, 5551
	opts.StreamOptions.StreamName = uniqueName(t, "tls-stream")
	t.Cleanup(func() {
		management(t, http.MethodDelete, "/api/queues/%2F/"+url.PathEscape(opts.StreamOptions.StreamName), nil)
	})
	return opts
}

func connectAndConsume(t *testing.T, opts *RabbitMQStreamOptions) error {
	t.Helper()
	client := NewRabbitMQStreamClient().SetRabbitMQOptions(opts)
	if _, err := client.Connect(); err != nil {
		return err
	}
	defer client.Close()
	// The consumer uses its own stream connection, which must also use TLS (and the same identity).
	_, err := client.Consume(func(stream.ConsumerContext, *streamamqp.Message) {})
	return err
}

func TestTLSWithCustomCA(t *testing.T) {
	opts := tlsTestOptions(t)
	opts.TLSAuthWithCACert, opts.CACert = true, tlsFile(t, "ca.pem")
	if err := connectAndConsume(t, opts); err != nil {
		t.Fatalf("TLS with the broker's CA: %v", err)
	}
}

func TestTLSRejectsABrokerSignedByAnotherCA(t *testing.T) {
	opts := tlsTestOptions(t)
	opts.TLSAuthWithCACert, opts.CACert = true, tlsFile(t, "other-ca.pem")
	err := connectAndConsume(t, opts)
	if err == nil || !strings.Contains(err.Error(), "certificate") {
		t.Fatalf("expected a certificate verification error, got %v", err)
	}
}

func TestTLSSkipVerify(t *testing.T) {
	opts := tlsTestOptions(t)
	opts.TLSSkipVerify = true
	if err := connectAndConsume(t, opts); err != nil {
		t.Fatalf("TLS with skip verify: %v", err)
	}
}

func TestMutualTLSWithExternalAuthentication(t *testing.T) {
	// The client certificate's CN is the RabbitMQ user; EXTERNAL needs it to exist (no password needed).
	const user = "e2e-tls-client"
	management(t, http.MethodPut, "/api/users/"+user, map[string]any{"password_hash": "", "tags": ""})
	management(t, http.MethodPut, "/api/permissions/%2F/"+user, map[string]any{"configure": ".*", "write": ".*", "read": ".*"})

	opts := tlsTestOptions(t)
	opts.SASLMechanism = SASLMechanismExternal
	opts.User, opts.Password = "", ""
	opts.TLSAuthWithCACert, opts.CACert = true, tlsFile(t, "ca.pem")
	opts.TLSAuth, opts.ClientCert, opts.ClientKey = true, tlsFile(t, "client.pem"), tlsFile(t, "client-key.pem")
	if err := connectAndConsume(t, opts); err != nil {
		t.Fatalf("mTLS + EXTERNAL: %v", err)
	}
}
